(()=>{
const by=id=>document.getElementById(id), colors=['#ffab91','#a5d7ff','#d4f179','#f4b8e8'];
const section=document.createElement('section');section.id='game';section.className='game hidden';section.setAttribute('aria-label','Gra: wszyscy do swoich pokojów');section.innerHTML=`<div class="game-head"><h2>kto znowu łazi?!</h2><button class="game-close" aria-label="Zamknij grę">×</button></div><p>Na korytarzu? <b>Kliknij, żeby zawrócił.</b> Już w cudzym pokoju? <b>Przeciągnij do jego numeru.</b><br>Możesz też kliknąć intruza, a potem właściwy pokój. Masz minutę. Ogarnij tę wycieczkę.</p><div class="game-stats"><span id="gameTime">60 s</span><span id="gameScore">0 pkt</span><span id="gameWrong">0 nie u siebie</span></div><div class="board" id="board"><div class="hall-label">korytarz · tu absolutnie nikt nie śpi</div></div><div class="game-message" id="gameMessage" aria-live="polite">ziemniak dostał dyżur. pomóż ziemniakowi.</div><div class="game-controls"><button id="gameStart">zaczynamy ten cyrk</button><button id="gamePause" class="hidden">pauza</button><small>klik: +1 · odstawienie intruza: +3</small></div>`;
document.querySelector('main').append(section);const launch=document.createElement('button');launch.className='bigbtn';launch.id='playGame';launch.textContent='ktoś łazi po korytarzu 👀';document.querySelector('.buttons').append(launch);
const board=by('board'),rooms=[];let people=[],running=false,paused=false,elapsed=0,spawnIn=0,score=0,lastFrame=0,raf=0,uid=0,selected=null,drag=null;
for(let i=0;i<4;i++){const room=document.createElement('button');room.className='room';room.style.left=(1+i*25)+'%';room.style.setProperty('--room',colors[i]);room.dataset.room=i;room.setAttribute('aria-label','Pokój '+(i+1));room.innerHTML=`${i+1}<small>pokój ${i+1}</small>`;room.onclick=()=>{if(selected!==null&&running&&!paused)deliver(selected,i)};board.append(room);rooms.push(room)}
function message(t){by('gameMessage').textContent=t}
function stats(){by('gameScore').textContent=score+' pkt';by('gameWrong').textContent=people.filter(p=>p.state==='wrong').length+' nie u siebie';by('gameTime').textContent=Math.max(0,Math.ceil(60-elapsed))+' s'}
function clearSelection(){selected=null;people.forEach(p=>p.el.classList.remove('chosen'));rooms.forEach(r=>r.classList.remove('selected'))}
function remove(p){p.el.remove();people=people.filter(x=>x!==p);if(selected===p.id)clearSelection();stats()}
function deliver(id,room){const p=people.find(p=>p.id===id);if(!p||p.state!=='wrong')return;if(p.home===room){score+=3;message(['dobra, teraz własne łóżko.','to TWÓJ pokój. zapamiętaj.','przesyłka dostarczona. dobranoc.'][score%3]);remove(p)}else{message('nie ten! numer na piżamie = numer pokoju.');position(p)}}
function position(p){p.el.style.left=p.x+'%';p.el.style.top=p.y+'%'}
function choose(p){clearSelection();selected=p.id;p.el.classList.add('chosen');rooms[p.home].classList.add('selected');message('teraz pokój '+(p.home+1)+'. tam jest jego poduszka.')}
function add(wrong=false){const home=Math.floor(Math.random()*4),target=(home+1+Math.floor(Math.random()*3))%4,id=++uid,el=document.createElement('button');const p={id,home,target,state:wrong?'wrong':'walking',t:0,duration:7+Math.random()*4,x:13+home*25,y:34,el};el.className='person '+p.state;el.style.setProperty('--person',colors[home]);el.textContent=home+1;el.setAttribute('aria-label',`Uczestnik z pokoju ${home+1}${wrong?', w złym pokoju':''}`);if(wrong){p.x=target*25+8+Math.random()*9;p.y=25}position(p);board.append(el);people.push(p);
el.onclick=()=>{if(!running||paused||el.dataset.dragged==='yes')return;if(p.state==='walking'){score++;message(['wracaj do łóżka.','nie, kuchnia też już śpi.','złapany na gorącym kapciu.'][score%3]);remove(p)}else choose(p)};
el.onpointerdown=e=>{if(!running||paused||p.state!=='wrong')return;drag={p,x:e.clientX,y:e.clientY,moved:false};el.setPointerCapture(e.pointerId);el.dataset.dragged='no'};
el.onpointermove=e=>{if(!drag||drag.p!==p)return;const rect=board.getBoundingClientRect();if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>5)drag.moved=true;if(!drag.moved)return;el.classList.add('dragging');el.style.left=Math.max(2,Math.min(98,(e.clientX-rect.left)/rect.width*100))+'%';el.style.top=Math.max(3,Math.min(95,(e.clientY-rect.top)/rect.height*100))+'%'};
el.onpointerup=e=>{if(!drag||drag.p!==p)return;const moved=drag.moved;drag=null;el.classList.remove('dragging');if(!moved)return;el.dataset.dragged='yes';const hit=rooms.find(r=>{const b=r.getBoundingClientRect();return e.clientX>=b.left&&e.clientX<=b.right&&e.clientY>=b.top&&e.clientY<=b.bottom});if(hit)deliver(id,Number(hit.dataset.room));else{position(p);message('upuść na drzwiach właściwego pokoju.')}setTimeout(()=>{el.dataset.dragged='no'},0)};
el.onpointercancel=()=>{drag=null;el.classList.remove('dragging');position(p)};stats()}
function frame(time){if(!running)return;const dt=Math.min((time-lastFrame)/1000,.1);lastFrame=time;if(!paused){elapsed+=dt;spawnIn-=dt;if(spawnIn<=0&&people.length<10){add();spawnIn=Math.max(1.25,3-elapsed/35)}for(const p of people){if(p.state!=='walking')continue;p.t+=dt/p.duration;const t=Math.min(1,p.t),a=13+p.home*25,b=13+p.target*25;if(t<.2){p.x=a;p.y=34+t/.2*28}else if(t<.8){p.x=a+(b-a)*(t-.2)/.6;p.y=62}else{p.x=b;p.y=62-(t-.8)/.2*34}position(p);if(t>=1){p.state='wrong';p.x=p.target*25+8+Math.random()*9;p.y=26+Math.random()*5;p.el.className='person wrong';p.el.setAttribute('aria-label',`Uczestnik z pokoju ${p.home+1}, w złym pokoju`);position(p);message('wlazł do cudzego. teraz trzeba go przenieść.')}}stats();if(elapsed>=60){finish();return}}raf=requestAnimationFrame(frame)}
function finish(){running=false;clearSelection();by('gamePause').classList.add('hidden');by('gameStart').textContent='jeszcze jedna nocka';message(`koniec dyżuru! ${score} pkt. ${people.filter(p=>p.state==='wrong').length} osób dalej nie u siebie. ziemniak ${score>=30?'jest dumny.':'potrzebuje urlopu.'}`)}
function start(){cancelAnimationFrame(raf);people.forEach(p=>p.el.remove());people=[];drag=null;clearSelection();elapsed=0;score=0;spawnIn=2.5;running=true;paused=false;by('gameStart').textContent='od nowa';by('gamePause').textContent='pauza';by('gamePause').classList.remove('hidden');add(true);add(true);add();message('dwóch już pomyliło pokoje. dobry początek.');lastFrame=performance.now();raf=requestAnimationFrame(frame)}
launch.onclick=()=>{quiet();section.classList.remove('hidden');section.scrollIntoView({behavior:'smooth',block:'start'})};by('gameStart').onclick=start;by('gamePause').onclick=()=>{paused=!paused;by('gamePause').textContent=paused?'gramy dalej':'pauza';message(paused?'wszyscy stoją. cud.':'dobra, pilnujemy dalej.')};section.querySelector('.game-close').onclick=()=>{running=false;cancelAnimationFrame(raf);section.classList.add('hidden');launch.focus()};document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!paused){paused=true;by('gamePause').textContent='gramy dalej';message('pauza. korytarz poczeka.')}});
})();
